const body = $input.first().json.body || $input.first().json;

let message = body.message || '';
const sessionId = body.sessionId || 'default';
const hasFiles = body.hasFiles || false;
const files = body.files || [];
let corpus = body.corpus;
const inlineContent = body.inlineContent;
const user = body.user || {};

// Extract user query from Open WebUI's wrapped format
// Format: <user_query>actual query</user_query>
const userQueryMatch = message.match(/<user_query>\s*([\s\S]*?)\s*<\/user_query>/i);
if (userQueryMatch) {
  message = userQueryMatch[1].trim();
}

// Also check for chat_history format: USER: message
const chatHistoryMatch = message.match(/USER:\s*([^\n<]+)/i);
if (chatHistoryMatch && !userQueryMatch) {
  message = chatHistoryMatch[1].trim();
}

// Extract corpus from message if not already set
if (!corpus) {
  const uploadMatch = message.match(/(?:upload|add|save)\s+(?:this\s+)?(?:to|into)\s+([\w-]+)/i);
  if (uploadMatch) {
    corpus = uploadMatch[1].toLowerCase();
  }
}

return [{
  json: {
    message,
    sessionId,
    hasFiles,
    files,
    corpus,
    inlineContent,
    user,
    messageLower: message.toLowerCase()
  }
}];

const input = $input.first().json;
const msg = input.messageLower;
const hasFiles = input.hasFiles;
const corpus = input.corpus;
const inlineContent = input.inlineContent;

let intent = 'query'; // default
let extractedQuery = input.message;

// List intent
if (msg.includes('list') || msg.includes('what knowledge') || 
    msg.includes('available collection') || msg.includes('what can you') ||
    msg.includes('show collection') || msg.includes('which corpus')) {
  intent = 'list';
}
// Status intent
else if (msg.includes('status') || msg.includes('statistics') || 
         msg.includes('how many document') || msg.includes('count')) {
  intent = 'status';
}
// Help intent
else if (msg.includes('help') || msg.includes('how do i') || 
         msg.includes('usage') || msg.includes('instructions')) {
  intent = 'help';
}
// Reload intent
else if (msg.includes('reload') || msg.includes('refresh all') || 
         msg.includes('reload all') || msg.includes('re-index')) {
  intent = 'reload';
}
// Upload intent
else if ((hasFiles || inlineContent || corpus) && 
         (msg.includes('upload') || msg.includes('add to') || 
          msg.includes('save to') || msg.includes('add this'))) {
  intent = 'upload';
}

return [{
  json: {
    ...input,
    intent,
    extractedQuery
  }
}];

// Read knowledge config and query Qdrant for stats
const config = {
  collections: [
    { name: 'capability-maps', description: 'Business capability models L1-L4', folder: 'capability-maps' },
    { name: 'reference-architectures', description: 'Standard architecture patterns and templates', folder: 'reference-architectures' },
    { name: 'guardrails-principles', description: 'ADRs, constraints, policies', folder: 'guardrails-principles' },
    { name: 'existing-landscape', description: 'Current system documentation', folder: 'existing-landscape' },
    { name: 'compliance-requirements', description: 'HIPAA, GDPR, SOC2 documentation', folder: 'compliance-requirements' },
    { name: 'data-standards', description: 'Data models, naming conventions', folder: 'data-standards' },
    { name: 'security-standards', description: 'Security policies, threat models', folder: 'security-standards' },
    { name: 'testing-standards', description: 'QA methodologies, test strategies', folder: 'testing-standards' }
  ]
};

// Query Qdrant for collection stats
const collections = [];
for (const col of config.collections) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://qdrant:6333/collections/${col.name}`,
      json: true
    });
    collections.push({
      name: col.name,
      description: col.description,
      documentCount: response.result?.points_count || 0,
      status: response.result?.status || 'unknown'
    });
  } catch (e) {
    collections.push({
      name: col.name,
      description: col.description,
      documentCount: 0,
      status: 'not_found'
    });
  }
}

// Format response
let output = '**Available Knowledge Collections**\n\n';
output += '| Collection | Description | Documents |\n';
output += '|------------|-------------|-----------|\n';

for (const col of collections) {
  output += `| ${col.name} | ${col.description} | ${col.documentCount} |\n`;
}

output += '\n**Usage:**\n';
output += '- Ask me any question and I\'ll search relevant collections\n';
output += '- Upload: Attach a .md file and say "upload to <collection>"\n';
output += '- Status: Say "knowledge status" for detailed stats\n';
output += '- Reload: Say "reload all knowledge" to refresh collections\n';

return [{
  json: {
    output,
    intent: 'list',
    collections
  }
}];

const collectionNames = [
  'capability-maps',
  'reference-architectures',
  'guardrails-principles',
  'existing-landscape',
  'compliance-requirements',
  'data-standards',
  'security-standards',
  'testing-standards'
];

const stats = [];
let totalDocs = 0;

for (const name of collectionNames) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://qdrant:6333/collections/${name}`,
      json: true
    });
    const count = response.result?.points_count || 0;
    totalDocs += count;
    stats.push({
      collection: name,
      documents: count,
      status: response.result?.status || 'green',
      vectorSize: response.result?.config?.params?.vectors?.size || 'N/A'
    });
  } catch (e) {
    stats.push({
      collection: name,
      documents: 0,
      status: 'not_created',
      vectorSize: 'N/A'
    });
  }
}

// Format response
let output = '**Knowledge Base Status**\n\n';
output += '| Collection | Documents | Status | Vector Size |\n';
output += '|------------|-----------|--------|-------------|\n';

for (const s of stats) {
  const statusIcon = s.status === 'green' ? '🟢' : (s.status === 'not_created' ? '⚪' : '🟡');
  output += `| ${s.collection} | ${s.documents} | ${statusIcon} ${s.status} | ${s.vectorSize} |\n`;
}

output += `\n**Total Documents:** ${totalDocs}\n`;
output += `**Collections:** ${stats.filter(s => s.status !== 'not_created').length}/${collectionNames.length} active\n`;

return [{
  json: {
    output,
    intent: 'status',
    stats,
    totalDocuments: totalDocs
  }
}];

const collectionNames = [
  'capability-maps',
  'reference-architectures',
  'guardrails-principles',
  'existing-landscape',
  'compliance-requirements',
  'data-standards',
  'security-standards',
  'testing-standards'
];

const results = [];

for (const collection of collectionNames) {
  try {
    // Call the Knowledge Loader - Generic workflow
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://n8n:5678/webhook/knowledge-loader',
      body: { collection },
      json: true
    });
    results.push({
      collection,
      status: response.status || 'completed',
      documentsLoaded: response.documentsLoaded || 0
    });
  } catch (e) {
    results.push({
      collection,
      status: 'error',
      error: e.message,
      documentsLoaded: 0
    });
  }
}

// Format response
let output = '🔄 **Reloading All Knowledge Collections**\n\n';
output += '| Collection | Status | Documents |\n';
output += '|------------|--------|-----------|\n';

let totalLoaded = 0;
for (const r of results) {
  const statusIcon = r.status === 'completed' ? '✅' : (r.status === 'no_files' ? '⚠️' : '❌');
  output += `| ${r.collection} | ${statusIcon} ${r.status} | ${r.documentsLoaded} |\n`;
  totalLoaded += r.documentsLoaded;
}

output += `\n**Total:** ${totalLoaded} documents loaded across ${results.filter(r => r.status === 'completed').length} collections.\n`;

return [{
  json: {
    output,
    intent: 'reload',
    results,
    totalLoaded
  }
}];

const input = $input.first().json;
let corpus = input.corpus;
const files = input.files || [];
const inlineContent = input.inlineContent;
const message = input.message || '';

// Extract corpus from message if not explicitly set
if (!corpus) {
  const uploadMatch = message.match(/(?:upload|add|save)\s+(?:to|into)\s+([\w-]+)/i);
  if (uploadMatch) {
    corpus = uploadMatch[1].toLowerCase();
  }
}

if (!corpus) {
  return [{
    json: {
      output: '❌ **Upload Error**\n\nPlease specify a collection to upload to.\n\nExample: "Upload to capability-maps" or "Add to agent-knowledge-business-analyst"\n\nAvailable collections:\n- General: capability-maps, reference-architectures, compliance-requirements, data-standards, security-standards, guardrails-principles, existing-landscape, testing-standards\n- Agent: agent-knowledge-business-analyst, agent-knowledge-architect, agent-knowledge-solution-architect, agent-knowledge-risk-assessor, agent-knowledge-test-strategist, agent-knowledge-project-manager, agent-knowledge-software-delivery',
      intent: 'upload',
      status: 'error',
      error: 'No corpus specified'
    }
  }];
}

// Validate corpus name
const validCorpora = [
  // General collections
  'capability-maps', 'reference-architectures', 'guardrails-principles',
  'existing-landscape', 'compliance-requirements', 'data-standards',
  'security-standards', 'testing-standards',
  // Agent-specific collections
  'agent-knowledge-business-analyst',
  'agent-knowledge-architect',
  'agent-knowledge-solution-architect',
  'agent-knowledge-risk-assessor',
  'agent-knowledge-test-strategist',
  'agent-knowledge-project-manager',
  'agent-knowledge-software-delivery'
];

if (!validCorpora.includes(corpus)) {
  return [{
    json: {
      output: `❌ **Unknown Collection**\n\nThe collection "${corpus}" does not exist.\n\n**Available collections:**\n\n*General:*\n${validCorpora.filter(c => !c.startsWith('agent-')).map(c => '- ' + c).join('\n')}\n\n*Agent-specific:*\n${validCorpora.filter(c => c.startsWith('agent-')).map(c => '- ' + c).join('\n')}`,
      intent: 'upload',
      status: 'error',
      error: 'Invalid corpus'
    }
  }];
}

let content = null;
let filename = 'uploaded_content.md';

// PRIORITY: Check files array FIRST (actual file uploads)
if (files.length > 0) {
  const file = files[0];
  // Check both 'name' (Open WebUI) and 'filename' (other sources)
  filename = file.name || file.filename || 'uploaded_file.md';

  // Decode base64 if needed
  if (file.encoding === 'base64' || (file.content && typeof file.content === 'string' && file.content.includes('base64'))) {
    try {
      let base64Data = file.content;
      if (base64Data.includes(',')) {
        base64Data = base64Data.split(',')[1];
      }
      content = Buffer.from(base64Data, 'base64').toString('utf-8');
    } catch (e) {
      content = file.content;
    }
  } else {
    content = file.content;
  }
}
// FALLBACK: Use inline content only if no files
else if (inlineContent) {
  content = inlineContent;
  filename = 'inline_content.md';
}

if (!content) {
  return [{
    json: {
      output: '❌ **No Content**\n\nPlease provide content to upload:\n- Attach a .md file, or\n- Include markdown content after the collection name\n\nExample: "Add to data-standards:\n\n# My Document\n\nContent here..."',
      intent: 'upload',
      status: 'error',
      error: 'No content provided'
    }
  }];
}

return [{
  json: {
    ...input,
    uploadContent: content,
    uploadFilename: filename,
    uploadCorpus: corpus
  }
}];

// Get data from Handle Upload node
const handleUploadData = $('Handle Upload').first().json;
const loaderResponse = $input.first().json;

// Extract values with fallbacks
const corpus = handleUploadData.uploadCorpus || loaderResponse.collection || 'unknown';
const filename = handleUploadData.uploadFilename || 'uploaded_file';
const status = loaderResponse.status || 'completed';
const docsLoaded = loaderResponse.documentsLoaded || 0;

let output = '';
if (status === 'completed' || status === 'success') {
  output = `✅ **Upload Successful**\n\n`;
  output += `**File:** ${filename}\n`;
  output += `**Collection:** ${corpus}\n`;
  output += `**Documents loaded:** ${docsLoaded}\n`;
  output += `\nYour knowledge has been added to the ${corpus} collection.`;
} else if (status === 'no_files') {
  output = `⚠️ **Upload Notice**\n\n`;
  output += `**Collection:** ${corpus}\n`;
  output += `**Status:** No files to process\n`;
  output += `\nThe loader found no files matching the expected patterns.`;
} else {
  output = `⚠️ **Upload Status: ${status}**\n\n`;
  output += `**File:** ${filename}\n`;
  output += `**Collection:** ${corpus}\n`;
  output += `**Details:** ${loaderResponse.message || 'Check the collection for updates.'}\n`;
}

return [{
  json: {
    output,
    intent: 'upload',
    status,
    collection: corpus,
    filename: filename,
    documentsLoaded: docsLoaded
  }
}];

const agentOutput = $input.first().json.output;

return [{
  json: {
    output: agentOutput,
    intent: 'query'
  }
}];
